```java
private static void scenarioInstallCancelDuringScan() throws Exception {
    System.out.println("===== D: action=install cancelled while the scan is in flight =====");
    Path dir = Files.createTempDirectory("ji-gate-d-");
    List<Map<String,String>> events = new CopyOnWriteArrayList<>();
    Fake runner = new Fake();
    runner.holdScan = true;
    Path archive = dir.resolve("ji-host.tar.gz");
    Files.writeString(archive, "synthetic archive");
    KeyPair pair = KeyPairGenerator.getInstance("Ed25519").generateKeyPair();
    Path manifest = dir.resolve("bundle.manifest.json");
    Path publicKey = dir.resolve("bundle.public.pem");
    writeBundle(archive, manifest, publicKey, pair);
    try (var orchestration = orchestration(runner, dir, events, Duration.ofSeconds(30), Duration.ofSeconds(30))) {
        var request = new RemoteOrchestration.Request("gate-d", RemoteOrchestration.Action.INSTALL,
            new RemoteOrchestration.Target("deploy-alias", Optional.empty(), OptionalInt.empty(), Optional.empty(), false),
            Optional.of(new RemoteOrchestration.Bundle(archive, manifest, publicKey)));
        String id = orchestration.submit(request).operationId();
        check("D1 install reaches the host key scan", await(() -> runner.scanStarted.getCount()==0, Duration.ofSeconds(10)));
        var cancelled = orchestration.cancel(id);
        check("D2 install cancel is cancelled", cancelled.state()==CANCELLED);
        check("D3 install cancel audits once", events.size()==1);
        runner.releaseScan.countDown();
        Thread.sleep(700);
        var settled = orchestration.get(id);
        check("D4 late scan keeps install cancelled", settled.state()==CANCELLED);
        check("D5 late scan adds no step", settled.steps().equals(cancelled.steps()));
        check("D6 late scan audits nothing", events.size()==1);
    }
}
```

